def design(x, kind):
    from itertools import combinations
    a = [np.ones(len(x)), *x.T]
    if kind in ('self23', 'pair2', 'all3'):
        a.extend([*(x * x).T, *(x ** 3).T])
    if kind in ('pair2', 'all3'):
        a.extend((x[:, i] * x[:, j] for (i, j) in combinations(range(4), 2)))
    if kind == 'all3':
        a.extend((x[:, i] ** 2 * x[:, j] for i in range(4) for j in range(4) if i != j))
        a.extend((x[:, i] * x[:, j] * x[:, k] for (i, j, k) in combinations(range(4), 3)))
    return np.array(a).T

def fit(a, y):
    b = np.linalg.lstsq(a, y, rcond=None)[0]
    for _ in range(35):
        r = y - a @ b
        r = r - np.median(r, axis=0)
        sc = np.maximum(1.4826 * np.median(abs(r), axis=0), 1e-07)
        for j in range(4):
            w = (1 + (r[:, j] / (2.5 * sc[j])) ** 2) ** (-0.5)
            b[:, j] = np.linalg.lstsq(a * w[:, None], y[:, j] * w, rcond=None)[0]
    return b
